from __future__ import annotations

import json
import sys
from pathlib import Path
from typing import Any

import numpy as np
import torch

TASK_DIR = Path(__file__).resolve().parent
SOURCE_DIR = TASK_DIR / "source"
OUTPUT_DIR = TASK_DIR / "outputs"

sys.path.insert(0, str(SOURCE_DIR))

from deepmd.dpmodel.model.spin_model import SpinModel as NumpySpinModel  # noqa: E402
from deepmd.pt.model.model.spin_model import SpinModel as TorchSpinModel  # noqa: E402
from deepmd.utils.spin import Spin  # noqa: E402


class _DummyNpBackbone:
    def get_dp_atomic_model(self) -> None:
        return None


class _DummyTorchBackbone(torch.nn.Module):
    def __init__(self) -> None:
        super().__init__()


def _build_model(backend: str) -> NumpySpinModel | TorchSpinModel:
    spin = Spin(use_spin=[True, False, True], virtual_scale=[0.5, 0.0, 0.75])
    if backend == "numpy":
        return NumpySpinModel(_DummyNpBackbone(), spin)
    return TorchSpinModel(_DummyTorchBackbone(), spin)


def _to_backend(array: np.ndarray, backend: str) -> Any:
    if backend == "torch":
        dtype = torch.long if np.issubdtype(array.dtype, np.integer) else torch.float64
        return torch.tensor(array, dtype=dtype)
    return array.copy()


def _clone(value: Any, backend: str) -> Any:
    if backend == "torch":
        return value.clone()
    return value.copy()


def _max_abs_delta(lhs: Any, rhs: Any, backend: str) -> float:
    if backend == "torch":
        return float(torch.max(torch.abs(lhs - rhs)).item())
    return float(np.max(np.abs(lhs - rhs)))


def _set_vectors(array: Any, indices: list[int], values: list[list[float]], backend: str) -> None:
    for index, value in zip(indices, values, strict=True):
        if backend == "torch":
            array[0, index] = torch.tensor(value, dtype=array.dtype, device=array.device)
        else:
            array[0, index] = np.array(value, dtype=array.dtype)


def _dense_fixture(name: str) -> dict[str, Any]:
    if name == "middle":
        return {
            "coord": np.array(
                [[[0.0, 0.1, 0.2], [1.0, 1.1, 1.2], [2.0, 2.1, 2.2]]],
                dtype=np.float64,
            ),
            "atype": np.array([[0, -1, 2]], dtype=np.int64),
            "background_positions": [1],
            "signal_position": 2,
        }
    return {
        "coord": np.array(
            [
                [
                    [0.0, 0.1, 0.2],
                    [1.0, 1.1, 1.2],
                    [2.0, 2.1, 2.2],
                    [3.0, 3.1, 3.2],
                ]
            ],
            dtype=np.float64,
        ),
        "atype": np.array([[2, 1, 0, -1]], dtype=np.int64),
        "background_positions": [3],
        "signal_position": 0,
    }


def _lower_fixture() -> dict[str, Any]:
    return {
        "coord": np.array(
            [
                [
                    [0.0, 0.1, 0.2],
                    [1.0, 1.1, 1.2],
                    [2.0, 2.1, 2.2],
                    [3.0, 3.1, 3.2],
                ]
            ],
            dtype=np.float64,
        ),
        "atype": np.array([[0, -1, 2, -1]], dtype=np.int64),
        "background_positions": [1, 3],
        "signal_position": 0,
        "nlist": np.array([[[2, -1], [0, -1]]], dtype=np.int64),
        "mapping": np.array([[0, 1, 0, 1]], dtype=np.int64),
    }


def _dense_virtual_index(position: int, nloc: int) -> int:
    return nloc + position


def _lower_virtual_index(position: int, nloc: int, nall: int) -> int:
    if position < nloc:
        return nloc + position
    return nloc + nall + (position - nloc)


def _input_response_dense(
    model: NumpySpinModel | TorchSpinModel,
    backend: str,
    fixture: dict[str, Any],
) -> dict[str, float]:
    coord = _to_backend(fixture["coord"], backend)
    atype = _to_backend(fixture["atype"], backend)
    spin_base = _to_backend(np.zeros_like(fixture["coord"]), backend)
    spin_background = _clone(spin_base, backend)
    spin_signal = _clone(spin_base, backend)

    _set_vectors(
        spin_background,
        fixture["background_positions"],
        [[0.3, -0.2, 0.4] for _ in fixture["background_positions"]],
        backend,
    )
    _set_vectors(spin_signal, [fixture["signal_position"]], [[-0.4, 0.5, -0.6]], backend)

    coord_base, _, corr_base = model.process_spin_input(
        _clone(coord, backend), _clone(atype, backend), _clone(spin_base, backend)
    )
    coord_background, _, corr_background = model.process_spin_input(
        _clone(coord, backend), _clone(atype, backend), _clone(spin_background, backend)
    )
    coord_signal, _, corr_signal = model.process_spin_input(
        _clone(coord, backend), _clone(atype, backend), _clone(spin_signal, backend)
    )

    return {
        "background_response_max_abs": max(
            _max_abs_delta(coord_base, coord_background, backend),
            _max_abs_delta(corr_base, corr_background, backend),
        ),
        "signal_response_max_abs": max(
            _max_abs_delta(coord_base, coord_signal, backend),
            _max_abs_delta(corr_base, corr_signal, backend),
        ),
    }


