def _output_response_dense(
    model: NumpySpinModel | TorchSpinModel,
    backend: str,
    fixture: dict[str, Any],
    *,
    use_scale_weight: bool,
) -> dict[str, float]:
    atype = _to_backend(fixture["atype"], backend)
    nloc = fixture["atype"].shape[1]
    out_base = _to_backend(np.ones((1, 2 * nloc, 3), dtype=np.float64), backend)
    out_background = _clone(out_base, backend)
    out_signal = _clone(out_base, backend)
    background_indices = [
        _dense_virtual_index(position, nloc) for position in fixture["background_positions"]
    ]
    signal_index = _dense_virtual_index(fixture["signal_position"], nloc)

    _set_vectors(
        out_background,
        background_indices,
        [[0.25, -0.5, 1.25] for _ in background_indices],
        backend,
    )
    _set_vectors(out_signal, [signal_index], [[-1.5, 0.75, 0.5]], backend)

    _, mag_base, _ = model.process_spin_output(
        _clone(atype, backend), _clone(out_base, backend), virtual_scale=use_scale_weight
    )
    _, mag_background, _ = model.process_spin_output(
        _clone(atype, backend),
        _clone(out_background, backend),
        virtual_scale=use_scale_weight,
    )
    _, mag_signal, _ = model.process_spin_output(
        _clone(atype, backend), _clone(out_signal, backend), virtual_scale=use_scale_weight
    )
    return {
        "background_response_max_abs": _max_abs_delta(mag_base, mag_background, backend),
        "signal_response_max_abs": _max_abs_delta(mag_base, mag_signal, backend),
    }


